// GameServerServiceServer is the server API for GameServerService service.
// All implementations must embed UnimplementedGameServerServiceServer
// for forward compatibility.
//
// 游戏服务器管理（权限 game:server）：接入（托管 / 仅 GM）、状态、进程、专用设置、更新、备份、文件与日志。
// 托管服务器的进程是应用实例（本机），控制台 WebSocket：/api/v1/game/server-console/ws?id=&role=；
// 实时动态（SSE，转发 MGP /events）：/api/v1/game/server-events/{id}。
type GameServerServiceServer interface {
	// 内置的游戏适配器
	ListGameAdapters(context.Context, *ListGameAdaptersRequest) (*ListGameAdaptersResponse, error)
	// 服务器列表（按游戏、接入方式、状态、标签筛选；搜索；分页）
	ListGameServers(context.Context, *ListGameServersRequest) (*ListGameServersResponse, error)
	// 服务器详情
	GetGameServer(context.Context, *GetGameServerRequest) (*GameServerInfo, error)
	// 接入服务器（仅 GM：MGP 地址与密钥；托管：服务端目录、端口与进程）
	CreateGameServer(context.Context, *CreateGameServerRequest) (*GameServerInfo, error)
	// 修改名称、标签、封面、备注、MGP 地址 / 密钥、通行证可见性与时区
	UpdateGameServer(context.Context, *UpdateGameServerRequest) (*GameServerInfo, error)
	// 删除服务器（删除接入记录与 Momoko 侧数据；托管时同时停止并删除它的托管进程）
	DeleteGameServer(context.Context, *DeleteGameServerRequest) (*DeleteGameServerResponse, error)
	// 测试 MGP 连接（传 id 时未填写的字段沿用已保存配置）
	TestGameServer(context.Context, *TestGameServerRequest) (*TestGameServerResponse, error)
	// 重新拉取 manifest 与 status
	RefreshGameServer(context.Context, *RefreshGameServerRequest) (*GameServerInfo, error)
	// 识别服务端目录（托管接入前的预检）：可执行文件、配置、端口、数据库、资源与端口占用
	DetectGameServerDir(context.Context, *DetectGameServerDirRequest) (*DetectGameServerDirResponse, error)
	// 切换接入方式（托管 ↔ 仅 GM）
	SwitchGameServerMode(context.Context, *SwitchGameServerModeRequest) (*GameServerInfo, error)
	// 轮换 MGP 密钥（托管：写回服务端配置，运行中按需重启）
	RotateGameServerKey(context.Context, *RotateGameServerKeyRequest) (*RotateGameServerKeyResponse, error)
	// 启动 / 停止 / 重启托管进程（role 为空表示全部进程）
	ControlGameServer(context.Context, *ControlGameServerRequest) (*GameServerInfo, error)
	// 清空托管进程控制台的输出记录（重新连接时不再回放）
	ClearGameServerConsole(context.Context, *ClearGameServerConsoleRequest) (*ClearGameServerConsoleResponse, error)
	// 修改托管选项（开机自启动、崩溃后自动重启、资源服务器）
	UpdateGameServerHosting(context.Context, *UpdateGameServerHostingRequest) (*GameServerInfo, error)
	// 概览：进程占用、实时 status、状态探测
	GetGameServerOverview(context.Context, *GetGameServerOverviewRequest) (*GameServerOverview, error)
	// 读取专用设置（适配器表单 + 配置原文 + 版本）
	GetGameServerSettings(context.Context, *GetGameServerSettingsRequest) (*GameServerSettings, error)
	// 保存专用设置（表单值或原文；revision 不一致时拒绝；可保存后重启）
	SaveGameServerSettings(context.Context, *SaveGameServerSettingsRequest) (*SaveGameServerSettingsResponse, error)
	// 当前服务端程序与最近的更新任务
	GetGameServerBuild(context.Context, *GetGameServerBuildRequest) (*GameServerBuild, error)
	// 检查候选构建（路径为服务端目录内的相对路径或本机绝对路径）
	CheckGameServerBuild(context.Context, *CheckGameServerBuildRequest) (*GameServerBuildInfo, error)
	// 更新服务端程序（后台任务：检查 → 停止 → 备份 → 替换 → 启动 → 健康检查，失败自动回滚）
	UpdateGameServerBuild(context.Context, *UpdateGameServerBuildRequest) (*GameServerTaskResponse, error)
	// 资源镜像：清单、发布状态、下载进度与资源服务器 /health
	GetGameServerResource(context.Context, *GetGameServerResourceRequest) (*GameServerResource, error)
	// 运行资源服务器的显式任务：verify 校验本地资源 / update 访问官方目录并下载
	RunGameServerResourceTask(context.Context, *RunGameServerResourceTaskRequest) (*GameServerTaskResponse, error)
	// 查看一个托管任务（更新、资源、备份、回档）
	GetGameServerTask(context.Context, *GetGameServerTaskRequest) (*GameServerTask, error)
	// 取消一个托管任务
	CancelGameServerTask(context.Context, *CancelGameServerTaskRequest) (*GameServerTask, error)
	// 变更记录（服务端、资源、配置、备份、密钥、接入方式）
	ListGameServerHistory(context.Context, *ListGameServerHistoryRequest) (*ListGameServerHistoryResponse, error)
	ListGameServerBackups(context.Context, *ListGameServerBackupsRequest) (*ListGameServerBackupsResponse, error)
	// 立即备份（后台任务）
	CreateGameServerBackup(context.Context, *CreateGameServerBackupRequest) (*GameServerTaskResponse, error)
	DeleteGameServerBackup(context.Context, *DeleteGameServerBackupRequest) (*DeleteGameServerBackupResponse, error)
	// 回档（后台任务：停止 → 备份当前 → 解压 → 启动）
	RestoreGameServerBackup(context.Context, *RestoreGameServerBackupRequest) (*GameServerTaskResponse, error)
	// 下载备份（预签名下载地址）
	DownloadGameServerBackup(context.Context, *DownloadGameServerBackupRequest) (*DownloadGameServerBackupResponse, error)
	// 定时备份与保留份数
	UpdateGameServerBackupPolicy(context.Context, *UpdateGameServerBackupPolicyRequest) (*GameServerBackupPolicy, error)
	// 服务端日志文件（适配器给出的模块）
	ListGameServerLogs(context.Context, *ListGameServerLogsRequest) (*ListGameServerLogsResponse, error)
	// 读取一个日志模块的最近记录（从末尾向前，按级别与关键字筛选）
	TailGameServerLog(context.Context, *TailGameServerLogRequest) (*TailGameServerLogResponse, error)
	GetGameServerFileList(context.Context, *GetInstanceFileListRequest) (*GetInstanceFileListResponse, error)
	GetGameServerFileTree(context.Context, *GetInstanceFileTreeRequest) (*GetInstanceFileTreeResponse, error)
	CreateGameServerFile(context.Context, *CreateInstanceFileRequest) (*CreateInstanceFileResponse, error)
	RenameGameServerFile(context.Context, *RenameInstanceFileRequest) (*RenameInstanceFileResponse, error)
	CopyGameServerFile(context.Context, *CopyInstanceFileRequest) (*CopyInstanceFileResponse, error)
	CutGameServerFile(context.Context, *CutInstanceFileRequest) (*CutInstanceFileResponse, error)
	DeleteGameServerFiles(context.Context, *BatchDeleteInstanceFileRequest) (*BatchDeleteInstanceFileResponse, error)
	CompressGameServerFiles(context.Context, *BatchCompressInstanceFileRequest) (*BatchCompressInstanceFileResponse, error)
	UnzipGameServerFile(context.Context, *UnzipInstanceFileRequest) (*UnzipInstanceFileResponse, error)
	EditGameServerFile(context.Context, *EditInstanceFileRequest) (*EditInstanceFileResponse, error)
	GameServerFilePreSign(context.Context, *InstanceFilePreSignRequest) (*InstanceFilePreSignResponse, error)
	GameServerFilePreSignUpload(context.Context, *InstanceFilePreSignUploadRequest) (*InstanceFilePreSignUploadResponse, error)
	mustEmbedUnimplementedGameServerServiceServer()
}

